/**
 * Global registry of contextual composer suggestions, the sibling of `welcomeOverrideLogic`: a host
 * surface registers suggestion groups that fit what the user is looking at, and the composer's empty
 * state shows them instead of the generic defaults while the provider stays registered.
 */
export const suggestionsOverrideLogic = kea<suggestionsOverrideLogicType>([
    path(['products', 'posthog_ai', 'frontend', 'logics', 'suggestionsOverrideLogic']),

    actions({
        /** Idempotent upsert — re-register the same `providerId` to update its suggestions. */
        registerSuggestions: (providerId: string, suggestions: readonly SuggestionGroup[]) => ({
            providerId,
            suggestions,
        }),
        deregisterSuggestions: (providerId: string) => ({ providerId }),
    }),

    reducers({
        providers: [
            {} as Record<string, readonly SuggestionGroup[]>,
            {
                registerSuggestions: (state, { providerId, suggestions }) => ({ ...state, [providerId]: suggestions }),
                deregisterSuggestions: (state, { providerId }) => {
                    if (!(providerId in state)) {
                        return state
                    }
                    const { [providerId]: _dropped, ...rest } = state
                    return rest
                },
            },
        ],
    }),

    selectors({
        // First registered provider with suggestions wins, mirroring `welcomeOverrideLogic`.
        overrideSuggestions: [
            (s) => [s.providers],
            (providers: Record<string, readonly SuggestionGroup[]>): readonly SuggestionGroup[] | null =>
                Object.values(providers).find((suggestions) => suggestions.length > 0) ?? null,
        ],
    }),
])
